const $=id=>document.getElementById(id);let externalAccount=null;let retirementAccounts=null;let manualHoldings=null;let transactionItems=[];let derivedPortfolioDocument=null;let activePresentationDocument=null;let activeHealthDocument=[];let activeRefreshDocument=null;let activeSummaryDocument=null;let transactionTotalDriver="price";let apiKey=sessionStorage.getItem("uiip-dashboard-key")||"";const titles={home:"Home",recommendations:"Recommendations",portfolio:"Portfolio",guild:"ETFs",homestead:"Household plan",watchtower:"Recession stress",transactions:"Transactions","refresh-page":"Refresh & Data Health",operations:"Operations"};const realmTitles={home:"The Hall",recommendations:"Counsel",portfolio:"The Treasury",guild:"Merchants' Guild",homestead:"The Homestead",watchtower:"The Watchtower",transactions:"Book of Deeds","refresh-page":"Vitals",operations:"The Workshop"};
