async function request(path,options={}){const headers={"X-API-Key":apiKey,"Accept":"application/json",...(options.headers||{})};const response=await fetch(path,{...options,headers});if(!response.ok){const body=await response.json().catch(()=>({}));const error=new Error(body.error?.message||`Request failed (${response.status})`);error.status=response.status;throw error}return response.json()}
