function money(value,currency){return new Intl.NumberFormat(undefined,{style:"currency",currency,maximumFractionDigits:2}).format(Number(value))}
function number(value,maximum=6){return new Intl.NumberFormat(undefined,{maximumFractionDigits:maximum}).format(Number(value))}
