function txnValue(item){if(item.price_per_unit===null||item.price_per_unit===undefined)return "Price unknown";return money(Number(item.quantity)*Number(item.price_per_unit)+Number(item.fees||0),item.currency)}
function mtgLaneLabel(lane){return{COLLECTOR_V1:"Collector box",PRE_COLLECTOR_V1:"Pre-Collector box",SECRET_LAIR_V1_1:"Secret Lair"}[lane]||String(lane||"").replace(/_/g," ")}
function txnAssetName(item){const p=(derivedPortfolioDocument?.positions||[]).find(x=>x.asset_id===item.asset_id);if(p&&p.asset_name)return uipCleanAssetName(p.asset_name);const tail=String(item.asset_id||"").split(":").pop();if(item.domain_id==="crypto")return tail.charAt(0).toUpperCase()+tail.slice(1);return tail||item.asset_id}
function renderTransactions(items){transactionItems=items;const search=($("txn-filter-search")?.value||"").trim().toLowerCase();const kind=$("txn-filter-type")?.value||"";const domain=$("txn-filter-domain")?.value||"";const filtered=items.filter(item=>{const haystack=[item.asset_id,txnAssetName(item),item.account_id,item.notes,item.transaction_id,item.external_reference].join(" ").toLowerCase();return(!search||haystack.includes(search))&&(!kind||item.transaction_type===kind)&&(!domain||item.domain_id===domain)});$("txn-history-count").textContent=`${filtered.length} shown · ${items.length} retained transaction${items.length===1?"":"s"}`;$("txn-history-empty").hidden=filtered.length>0;$("txn-history-empty").textContent=items.length&&!filtered.length?"No transactions match the current filters.":"No transactions have been recorded yet.";$("txn-history").innerHTML=filtered.map(item=>`<article class="transaction-row"><div class="transaction-row-head"><div><h4>${esc(txnAssetName(item))}</h4><small class="transaction-asset-id">${esc(item.asset_id)}</small><div class="transaction-row-meta"><span>${esc(item.domain_id.toUpperCase())}</span><span>${esc(item.account_id)}</span><span>${esc(new Date(item.occurred_at).toLocaleString())}</span></div></div><span class="txn-type">${esc(item.transaction_type)}</span></div><div class="transaction-row-meta"><span>Qty ${esc(quantityLabel(item.quantity))}</span><span>${esc(item.price_per_unit==null?"Price unknown":money(item.price_per_unit,item.currency)+" / unit")}</span><span>${esc(txnValue(item))}</span></div>${item.corrects_transaction_id?`<div class="correction-link">Corrects ${esc(item.corrects_transaction_id)} · ${esc(item.correction_reason||"")}</div>`:""}${item.notes?`<div class="transaction-row-note">${esc(item.notes)}</div>`:""}<div class="transaction-row-meta"><span>ID ${esc(item.transaction_id)}</span><span>Recorded ${esc(new Date(item.recorded_at).toLocaleString())}</span></div></article>`).join("");}
function refreshTransactionFilters(items){const select=$("txn-filter-domain");if(!select)return;const selected=select.value;const domains=[...new Set(items.map(item=>item.domain_id).filter(Boolean))].sort();select.innerHTML=`<option value="">All domains</option>${domains.map(domain=>`<option value="${esc(domain)}">${esc(domain.toUpperCase())}</option>`).join("")}`;select.value=domains.includes(selected)?selected:""}

