function syncTransactionAmounts(source){const quantity=Number($("txn-quantity")?.value||0);const priceInput=$("txn-price");const totalInput=$("txn-total");if(!priceInput||!totalInput)return;if(source==="total")transactionTotalDriver="total";if(source==="price")transactionTotalDriver="price";if(quantity>0&&transactionTotalDriver==="total"&&totalInput.value!==""){priceInput.value=String(Number(totalInput.value)/quantity)}else if(quantity>0&&transactionTotalDriver==="price"&&priceInput.value!==""){totalInput.value=String(quantity*Number(priceInput.value))}updateTransactionPositionContext()}
