;(()=>{/* The page CSP (style-src 'self') ignores inline data-css="" attributes; re-apply them through the CSSOM, which CSP allows. */const apply=root=>{if(!root||root.nodeType!==1)return;const nodes=root.hasAttribute("style")?[root,...root.querySelectorAll("[style]")]:root.querySelectorAll("[style]");for(const el of nodes){const css=el.getAttribute("style");if(css&&el.dataset.cspStyle!==css){el.style.cssText=css;el.dataset.cspStyle=el.getAttribute("style")}}};const start=()=>{apply(document.body);new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)apply(node)}).observe(document.body,{childList:true,subtree:true})};if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",start);else start()})();


